import{_ as e,o as h,c as t,a0 as a}from"./chunks/framework.DCluYYrN.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"vi_VN/guide/faq.md","filePath":"vi_VN/guide/faq.md"}'),o={name:"vi_VN/guide/faq.md"};function i(c,n,r,l,s,d){return h(),t("div",null,[...n[0]||(n[0]=[a('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="kernelsu-co-ho-tro-thiet-bi-cua-toi-khong" tabindex="-1">KernelSU có hỗ trợ thiết bị của tôi không? <a class="header-anchor" href="#kernelsu-co-ho-tro-thiet-bi-cua-toi-khong" aria-label="Permalink to &quot;KernelSU có hỗ trợ thiết bị của tôi không?&quot;">​</a></h2><p>KernelSU hỗ trợ các thiết bị chạy Android với bootloader đã mở khóa. Tuy nhiên, hỗ trợ chính thức chỉ dành cho GKI Linux Kernel 5.10+ (trong thực tế, điều này có nghĩa là thiết bị của bạn cần có Android 12 out-of-the-box để được hỗ trợ).</p><p>Bạn có thể dễ dàng kiểm tra hỗ trợ cho thiết bị của mình thông qua ứng dụng quản lý KernelSU, có sẵn <a href="https://github.com/tiann/KernelSU/releases" target="_blank" rel="noreferrer">tại đây</a>.</p><p>Nếu ứng dụng hiển thị <code>Not installed</code>, điều đó có nghĩa là thiết bị của bạn được KernelSU hỗ trợ chính thức.</p><p>Nếu ứng dụng hiển thị <code>Unsupported</code>, điều đó có nghĩa là thiết bị của bạn hiện không được hỗ trợ chính thức. Tuy nhiên, bạn có thể build mã nguồn kernel và tích hợp KernelSU để làm cho nó hoạt động, hoặc sử dụng <a href="./unofficially-support-devices.html">Thiết bị được hỗ trợ không chính thức</a>.</p><h2 id="kernelsu-co-can-mo-khoa-bootloader-khong" tabindex="-1">KernelSU có cần mở khóa bootloader không? <a class="header-anchor" href="#kernelsu-co-can-mo-khoa-bootloader-khong" aria-label="Permalink to &quot;KernelSU có cần mở khóa bootloader không?&quot;">​</a></h2><p>Chắc chắn rồi.</p><h2 id="kernelsu-co-ho-tro-module-khong" tabindex="-1">KernelSU có hỗ trợ module không? <a class="header-anchor" href="#kernelsu-co-ho-tro-module-khong" aria-label="Permalink to &quot;KernelSU có hỗ trợ module không?&quot;">​</a></h2><p>Có, hầu hết các module Magisk hoạt động trên KernelSU. Tuy nhiên, nếu module của bạn cần sửa đổi các tệp <code>/system</code>, bạn cần cài đặt <a href="./metamodule.html">metamodule</a> (chẳng hạn như <code>meta-overlayfs</code>). Các tính năng module khác hoạt động mà không cần metamodule. Kiểm tra <a href="./module.html">Hướng dẫn Module</a> để biết thêm thông tin.</p><h2 id="kernelsu-co-ho-tro-xposed-khong" tabindex="-1">KernelSU có hỗ trợ Xposed không? <a class="header-anchor" href="#kernelsu-co-ho-tro-xposed-khong" aria-label="Permalink to &quot;KernelSU có hỗ trợ Xposed không?&quot;">​</a></h2><p>Có, bạn có thể sử dụng LSPosed (hoặc các phái sinh Xposed hiện đại khác) với <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a>.</p><h2 id="kernelsu-co-ho-tro-zygisk-khong" tabindex="-1">KernelSU có hỗ trợ Zygisk không? <a class="header-anchor" href="#kernelsu-co-ho-tro-zygisk-khong" aria-label="Permalink to &quot;KernelSU có hỗ trợ Zygisk không?&quot;">​</a></h2><p>KernelSU không có hỗ trợ Zygisk tích hợp sẵn, nhưng bạn có thể sử dụng module như <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> để hỗ trợ nó.</p><h2 id="kernelsu-co-tuong-thich-voi-magisk-khong" tabindex="-1">KernelSU có tương thích với Magisk không? <a class="header-anchor" href="#kernelsu-co-tuong-thich-voi-magisk-khong" aria-label="Permalink to &quot;KernelSU có tương thích với Magisk không?&quot;">​</a></h2><p>Hệ thống module của KernelSU xung đột với magic mount của Magisk. Nếu có bất kỳ module nào được kích hoạt trong KernelSU, toàn bộ Magisk sẽ ngừng hoạt động.</p><p>Tuy nhiên, nếu bạn chỉ sử dụng <code>su</code> của KernelSU, nó sẽ hoạt động tốt với Magisk. KernelSU sửa đổi <code>kernel</code>, trong khi Magisk sửa đổi <code>ramdisk</code>, cho phép cả hai hoạt động cùng nhau.</p><h2 id="kernelsu-se-thay-the-magisk" tabindex="-1">KernelSU sẽ thay thế Magisk? <a class="header-anchor" href="#kernelsu-se-thay-the-magisk" aria-label="Permalink to &quot;KernelSU sẽ thay thế Magisk?&quot;">​</a></h2><p>Chúng tôi tin rằng không, và đó không phải là mục tiêu của chúng tôi. Magisk đã đủ tốt cho giải pháp root userspace và sẽ tồn tại lâu dài. Mục tiêu của KernelSU là cung cấp giao diện kernel cho người dùng, không phải để thay thế Magisk.</p><h2 id="kernelsu-co-the-ho-tro-cac-thiet-bi-khong-phai-gki-khong" tabindex="-1">KernelSU có thể hỗ trợ các thiết bị không phải GKI không? <a class="header-anchor" href="#kernelsu-co-the-ho-tro-cac-thiet-bi-khong-phai-gki-khong" aria-label="Permalink to &quot;KernelSU có thể hỗ trợ các thiết bị không phải GKI không?&quot;">​</a></h2><p>Có thể. Nhưng bạn cần tải xuống mã nguồn kernel và tích hợp KernelSU vào source tree, sau đó tự biên dịch kernel.</p><h2 id="kernelsu-co-the-ho-tro-cac-thiet-bi-duoi-android-12-khong" tabindex="-1">KernelSU có thể hỗ trợ các thiết bị dưới Android 12 không? <a class="header-anchor" href="#kernelsu-co-the-ho-tro-cac-thiet-bi-duoi-android-12-khong" aria-label="Permalink to &quot;KernelSU có thể hỗ trợ các thiết bị dưới Android 12 không?&quot;">​</a></h2><p>Chính kernel thiết bị ảnh hưởng đến khả năng tương thích của KernelSU, và nó không liên quan gì đến phiên bản Android. Hạn chế duy nhất là các thiết bị được ra mắt với Android 12 phải có phiên bản kernel 5.10+ (thiết bị GKI). Vì vậy:</p><ol><li>Các thiết bị được ra mắt với Android 12 phải được hỗ trợ.</li><li>Các thiết bị có kernel cũ (một số thiết bị với Android 12 cũng có kernel cũ) tương thích (bạn cần tự build kernel).</li></ol><h2 id="kernelsu-co-the-ho-tro-kernel-cu-khong" tabindex="-1">KernelSU có thể hỗ trợ kernel cũ không? <a class="header-anchor" href="#kernelsu-co-the-ho-tro-kernel-cu-khong" aria-label="Permalink to &quot;KernelSU có thể hỗ trợ kernel cũ không?&quot;">​</a></h2><p>Có thể. KernelSU hiện đã được backport cho kernel 4.14. Đối với các kernel cũ hơn, bạn cần tự backport, và PR luôn được chào đón!</p><h2 id="lam-cach-nao-đe-tich-hop-kernelsu-cho-kernel-cu" tabindex="-1">Làm cách nào để tích hợp KernelSU cho kernel cũ? <a class="header-anchor" href="#lam-cach-nao-đe-tich-hop-kernelsu-cho-kernel-cu" aria-label="Permalink to &quot;Làm cách nào để tích hợp KernelSU cho kernel cũ?&quot;">​</a></h2><p>Vui lòng kiểm tra hướng dẫn <a href="./how-to-integrate-for-non-gki.html">Tích hợp cho thiết bị không phải GKI</a>.</p><h2 id="tai-sao-phien-ban-android-cua-toi-la-13-nhung-kernel-hien-thi-android12-5-10" tabindex="-1">Tại sao phiên bản Android của tôi là 13, nhưng kernel hiển thị &quot;android12-5.10&quot;? <a class="header-anchor" href="#tai-sao-phien-ban-android-cua-toi-la-13-nhung-kernel-hien-thi-android12-5-10" aria-label="Permalink to &quot;Tại sao phiên bản Android của tôi là 13, nhưng kernel hiển thị &quot;android12-5.10&quot;?&quot;">​</a></h2><p>Phiên bản kernel không liên quan gì đến phiên bản Android. Nếu bạn cần flash kernel, luôn sử dụng phiên bản kernel; phiên bản Android không quan trọng bằng.</p><h2 id="toi-la-gki-1-0-toi-co-the-su-dung-đieu-nay-khong" tabindex="-1">Tôi là GKI 1.0, tôi có thể sử dụng điều này không? <a class="header-anchor" href="#toi-la-gki-1-0-toi-co-the-su-dung-đieu-nay-khong" aria-label="Permalink to &quot;Tôi là GKI 1.0, tôi có thể sử dụng điều này không?&quot;">​</a></h2><p>GKI 1.0 hoàn toàn khác với GKI 2.0, bạn phải tự biên dịch kernel.</p><h2 id="lam-cach-nao-đe-lam-cho-system-rw" tabindex="-1">Làm cách nào để làm cho <code>/system</code> RW? <a class="header-anchor" href="#lam-cach-nao-đe-lam-cho-system-rw" aria-label="Permalink to &quot;Làm cách nào để làm cho `/system` RW?&quot;">​</a></h2><p>Chúng tôi không khuyến nghị bạn sửa đổi trực tiếp phân vùng hệ thống. Vui lòng kiểm tra <a href="./module.html">Hướng dẫn Module</a> để sửa đổi nó một cách systemless. Nếu bạn khăng khăng làm điều này, hãy kiểm tra <a href="https://github.com/HuskyDG/magic_overlayfs" target="_blank" rel="noreferrer">magisk_overlayfs</a>.</p><h2 id="kernelsu-co-the-sua-đoi-hosts-khong-lam-cach-nao-đe-su-dung-adaway" tabindex="-1">KernelSU có thể sửa đổi hosts không? Làm cách nào để sử dụng AdAway? <a class="header-anchor" href="#kernelsu-co-the-sua-đoi-hosts-khong-lam-cach-nao-đe-su-dung-adaway" aria-label="Permalink to &quot;KernelSU có thể sửa đổi hosts không? Làm cách nào để sử dụng AdAway?&quot;">​</a></h2><p>Tất nhiên. Nhưng KernelSU không có hỗ trợ hosts tích hợp sẵn, bạn có thể cài đặt module như <a href="https://github.com/symbuzzer/systemless-hosts-KernelSU-module" target="_blank" rel="noreferrer">systemless-hosts</a> để thực hiện.</p><h2 id="tai-sao-cac-module-cua-toi-khong-hoat-đong-sau-khi-cai-đat-moi" tabindex="-1">Tại sao các module của tôi không hoạt động sau khi cài đặt mới? <a class="header-anchor" href="#tai-sao-cac-module-cua-toi-khong-hoat-đong-sau-khi-cai-đat-moi" aria-label="Permalink to &quot;Tại sao các module của tôi không hoạt động sau khi cài đặt mới?&quot;">​</a></h2><p>Nếu các module của bạn cần sửa đổi các tệp <code>/system</code>, bạn cần cài đặt <a href="./metamodule.html">metamodule</a> để mount thư mục <code>system</code>. Các tính năng module khác (scripts, sepolicy, system.prop) hoạt động mà không cần metamodule.</p><p><strong>Giải pháp</strong>: Xem <a href="./metamodule.html">Hướng dẫn Metamodule</a> để biết hướng dẫn cài đặt.</p><h2 id="metamodule-la-gi-va-tai-sao-toi-can-no" tabindex="-1">Metamodule là gì và tại sao tôi cần nó? <a class="header-anchor" href="#metamodule-la-gi-va-tai-sao-toi-can-no" aria-label="Permalink to &quot;Metamodule là gì và tại sao tôi cần nó?&quot;">​</a></h2><p>Metamodule là một module đặc biệt cung cấp cơ sở hạ tầng để mount các module thông thường. Xem <a href="./metamodule.html">Hướng dẫn Metamodule</a> để biết giải thích đầy đủ.</p>',41)])])}const k=e(o,[["render",i]]);export{u as __pageData,k as default};
